from pathlib import Path
import json
S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text('utf-8-sig'));p=S/'analysis/SuperSDS.json';out=json.loads(p.read_text('utf-8-sig')) if p.exists() else {}
base={'滑價xTick':'純數×商品最小跳動；尾%為成交價百分比。總FIFO每次配對扣2×退出價滑價，子策略現金流則各成交側扣自己的滑價，百分比時兩者可不同；dayswap類型為0。','計算DD方式':'交易時計算只由配對交易更新；每日於每資料日close虛擬平開，每月於次筆月份改變前close平開。一般dayswap零滑價；session=1真換約仍是有滑價swap。','策略方向':'訊號算出目標後，只多把空目標改0、只空把多目標改0、多空都作保留；會把相反訊號變成平倉，非直接忽略。','部位管理':'固定一口每訊號單位1；固定額每單位=固定金額÷(本次價格×契約價值)，可小數。加碼按本次價換新單位，減碼按原實際量比例，持倉同訊號不每日再平衡。','固定金額':'直接用此數值，不乘萬倍率；除本次成交價×商品契約價值後按整數口數／最小口數處理，負資金或負最小口數會拋錯。','最小口數':'僅固定額，用max(算出單位口數,此值)，可設0；這是每訊號單位的底量，不是總部位上限。','整數口數':'固定額時先floor每新增單位量，再套最小口數；同向減碼比例後也floor絕對實際量，否則保留decimal小數。','ATR長度':'準備資料時對ATR做平均，附成交紀錄與匯出欄；本策略實際換量只用固定額／價格／契約價值，不依此ATR作風險配量。'}
cost='同一策略實例內所有子項的真實口數共用FIFO，不按子策略ID分帳；損益=(價差−2×退出價滑價)×配對口數，不再乘契約價值。子項自己的現金流逐側扣成本，百分比滑價時可與總FIFO不同。'
swap='共用收盤處理在session=1以本日close平舊、close+delta重開原實際口數；一般DD平開用dayswap零滑價且不計普通交易次數。最末再以最後close真實平倉。'
def add(name,summary,family,en,ex,me,ca,notes={}):
 iid='SuperSDS/Stg'+name;ns=base|notes;out[iid]={'summary':summary,'family':family,'entry':en,'exit':ex,'mechanics':me,'caveats':ca,'parameterNotes':{q['name']:ns[q['name']] for q in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
add('BuyHold','在回測第一日開盤建立單一方向，維持原實際口數跨期持有，最後收盤退出。','定期與持有',['只作多或只作空時，在第一筆資料open、標記09:00建立1個訊號單位；固定額可換成不同實際量。'],['沒有價格停損或動態訊號退出；末筆13:30標記的close平倉。'],[cost,swap],['方向選多空都作會顯示提示直接不交易，不會自動選多或同時買空。','固定額只在初次入場換量，換約保留原實際量，並非資金隨價格每日重設的等金額持有。'],{'策略方向':'只作多／只作空決定首日方向；多空都作直接提示並返回，不產生交易。'})
add('MA','以昨日收盤均線的外帶判斷今日開盤突破，回越中線平倉，也可直接反手。','均線與區間突破',['由前N筆含昨日close算SMA，以MA±點數或百分比距離為外帶；從第N筆後的今日open比較，嚴格>上帶多、<下帶空。'],['未突破反向外帶時，舊多open<均線平、舊空open>均線平；等號不退出。','相反外帶優先算反向目標，先在本日open退舊再同價進新；最後close清倉。'],[cost,swap,'均線窗口以原始close相加，不用SMS那個aux換約乘數修正；僅日open判斷，不以日high／low觸價。'],['突破條件在中線退出之前；負距離可使帶交錯，程式未自動重排，仍先上帶分支。'],{'均線天數':'SMA窗口長度，今日以昨日索引值作比較，從i=N開始交易，窗口是前N個close。','突破區間':'純數為均線兩側點數，尾%為均線百分比；上MA+距離、下MA−距離。只有嚴格越外帶才改方向。'})
add('SMS','昨日收盤相對更早調整收盤的動量外帶決定今日開盤多空，回到基準內側退出，可選結算平倉。','動量與趨勢',['SM[k]=第k−N筆close×其換約乘數÷第k筆乘數，不是N日平均；以昨日close嚴格>SM+距離作多、<SM−距離作空，在今日open執行。'],['未越反向外帶時，舊多昨日close<=SM平、舊空>=SM平；同根相反外帶則先平後反手。','結算動作=出場且本日session=1，當日close平；選換倉走共用平舊再開。最末close仍真平。'],[cost,swap,'從i=N+1開始，昨日訊號今日open成交並標09:00；方向濾網將不允許的相反目標改0。'],['SM使用比例換約因子校正歷史端點，其他日均線策略未必相同。結算日早上仍可能新進，收盤再依出場選項退出。'],{'動量天數':'昨日索引k往前N筆的close作比較基準，先做aux換約乘數比例換算；不是N日SMA，i=N+1才開始。','突破區間':'在校正SM上加減點數或百分比，外帶嚴格突破進場，回基準則多<=／空>=退出。','結算動作':'出場在session=1當日close平，不立即重開；換倉則由共用收盤以close→close+delta保留原實際量。'})
add('BreakOut','今日開盤突破長期開盤極值帶建立方向，落到短期開盤帶之外退出，反向長帶可直接反手。','均線與區間突破',['前長期天數的open極大／極小作長帶，今日open嚴格>長高多、<長低空。從長短窗口較大值後開始。'],['沒越長帶才查短帶：open<短低或>短高都把目標改0，與現有方向無關；因此多單也會因突破短高而退出。','先算長帶多空，再短帶平，方向濾網後在同日open平舊／開新，末筆close清倉。'],[cost,swap,'CalcHighLow現版用每日open極值，不是high／low；長短帶都只看前一索引，排除今日。'],['策略原描述只說長高進多／短低退，但實際含空向長低與任一側短帶退出，且短帶退出未依持倉方向分邊。'],{'短天期天數':'前此筆數open的高低帶，未觸長帶時今日open超任一側短帶就目標0；不是只拿多短低／空短高。','長天期天數':'前此筆數open極值帶，嚴格上破多、下破空且優先短帶退出；歷史high／low不參與。'})
p.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote SDS initial4')
